{
  "story": "Why does networking need seven OSI layers? Follow one message, “Hi,” from the Sender through the Signal path to the Receiver. Compare the recovered message with the original. Assume successful delivery; protocol examples illustrate responsibilities, not seven mandatory software modules.",
  "aha": {
    "stateId": "recovered",
    "observation": "The Receiver recovers the original message because the layers perform different jobs around the same application data."
  },
  "layout": {
    "preset": "protocol",
    "width": 640
  },
  "parts": [
    {
      "id": "journey-rail",
      "kind": "step-rail",
      "presentation": "Approved card shell; explanation above experiment; ordered state rail carries progress, never elapsed time. Brief parameter-control budget: zero; navigation is separate.",
      "bind": {
        "active": "state.id",
        "items": "variant.states"
      }
    },
    {
      "id": "delivery-picture",
      "kind": "fixed-picture",
      "presentation": "Canonical protocol composition with fixed Sender, Signal path, and Receiver. Highlight one active region; no animation or full layer matrix.",
      "bind": {
        "active": "state.active",
        "links": "variant.links",
        "regions": "variant.regions"
      }
    },
    {
      "id": "responsibility-callout",
      "kind": "active-callout",
      "presentation": "Anchor beside the named active region; reserve readable label space. Identify the location and explain its current responsibility.",
      "bind": {
        "target": "state.calloutRegion",
        "text": "state.sentence",
        "reason": "state.why"
      }
    },
    {
      "id": "evidence-and-status",
      "kind": "value-readout",
      "presentation": "Show message evidence and bound status below the picture; wrap long values. Reference capture shows recovered, held until learner action.",
      "bind": {
        "values": "state.readouts"
      }
    }
  ],
  "controls": [
    {
      "id": "step",
      "kind": "index",
      "label": "OSI journey",
      "items": "variant.states",
      "presentation": "Previous and Next; default index 0, bounds 0–7, increment 1. Keep boundary buttons named and disabled; support keyboard activation and visible focus."
    },
    {
      "id": "reset",
      "kind": "reset",
      "label": "Reset",
      "presentation": "Restore the first state and all defaults. Support keyboard activation and visible focus; no automatic advancement."
    }
  ],
  "data": {
    "variants": [
      {
        "label": "One message through seven responsibilities",
        "regions": [
          {
            "id": "sender",
            "label": "Sender",
            "actors": ["Sender"]
          },
          {
            "id": "signal-path",
            "label": "Signal path",
            "phases": ["Physical transmission"]
          },
          {
            "id": "receiver",
            "label": "Receiver",
            "actors": ["Receiver"]
          }
        ],
        "links": [
          {
            "from": "sender",
            "to": "signal-path",
            "label": "Transmit"
          },
          {
            "from": "signal-path",
            "to": "receiver",
            "label": "Receive"
          }
        ],
        "states": [
          {
            "id": "application",
            "label": "7 · Application",
            "short": "Application",
            "sentence": "Sender: Application provides network services used by applications, such as sending an HTTP message.",
            "why": "OSI describes responsibilities; this example uses HTTP, TCP, IP, and Ethernet without assuming a perfect OSI mapping.",
            "active": ["sender"],
            "calloutRegion": "sender",
            "readouts": [
              {
                "id": "original",
                "label": "Original message",
                "value": "Hi"
              },
              {
                "id": "representation",
                "label": "Current representation",
                "value": "Application message carrying “Hi”"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Application message ready; Next examines its representation."
              }
            ]
          },
          {
            "id": "presentation",
            "label": "6 · Presentation",
            "short": "Presentation",
            "sentence": "Sender: Presentation handles data representation, such as encoding text in UTF-8.",
            "why": "Both endpoints must interpret the representation consistently; encoding does not change the intended message.",
            "active": ["sender"],
            "calloutRegion": "sender",
            "readouts": [
              {
                "id": "original",
                "label": "Original message",
                "value": "Hi"
              },
              {
                "id": "representation",
                "label": "Current representation",
                "value": "Application message with “Hi” encoded as UTF-8 text"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Representation agreed; Next examines conversation management."
              }
            ]
          },
          {
            "id": "session",
            "label": "5 · Session",
            "short": "Session",
            "sentence": "Sender: Session manages the dialogue, including establishing, coordinating, and ending conversations.",
            "why": "Internet applications may implement these responsibilities themselves; a separate session-layer header is not required.",
            "active": ["sender"],
            "calloutRegion": "sender",
            "readouts": [
              {
                "id": "original",
                "label": "Original message",
                "value": "Hi"
              },
              {
                "id": "representation",
                "label": "Current representation",
                "value": "Same encoded application message, within a managed conversation"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Conversation context ready; Next examines end-to-end transport."
              }
            ]
          },
          {
            "id": "transport",
            "label": "4 · Transport",
            "short": "Transport",
            "sentence": "Sender: Transport provides process-to-process delivery; TCP adds ordering and retransmission for reliable transfer.",
            "why": "In this simplified example, TCP places the application message inside one segment and identifies the communicating processes using ports.",
            "active": ["sender"],
            "calloutRegion": "sender",
            "readouts": [
              {
                "id": "original",
                "label": "Original message",
                "value": "Hi"
              },
              {
                "id": "representation",
                "label": "Current representation",
                "value": "TCP segment containing the application message"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Transport information added; Next examines delivery across networks."
              }
            ]
          },
          {
            "id": "network",
            "label": "3 · Network",
            "short": "Network",
            "sentence": "Sender: Network provides addressing and routing between networks; IP carries the TCP segment toward its destination.",
            "why": "IP addresses identify network endpoints; routers use destination addressing to select forwarding paths.",
            "active": ["sender"],
            "calloutRegion": "sender",
            "readouts": [
              {
                "id": "original",
                "label": "Original message",
                "value": "Hi"
              },
              {
                "id": "representation",
                "label": "Current representation",
                "value": "IP packet containing the TCP segment"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Network information added; Next examines delivery over one link."
              }
            ]
          },
          {
            "id": "data-link",
            "label": "2 · Data link",
            "short": "Data link",
            "sentence": "Sender: Data link packages the IP packet for one local link, using an Ethernet frame in this example.",
            "why": "Link delivery reaches the next interface; it is different from routing across an entire network path.",
            "active": ["sender"],
            "calloutRegion": "sender",
            "readouts": [
              {
                "id": "original",
                "label": "Original message",
                "value": "Hi"
              },
              {
                "id": "representation",
                "label": "Current representation",
                "value": "Ethernet frame containing the IP packet"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Link information added; Next examines physical transmission."
              }
            ]
          },
          {
            "id": "physical",
            "label": "1 · Physical",
            "short": "Physical",
            "sentence": "Signal path: Physical carries encoded bits as electrical, optical, or radio signals.",
            "why": "The medium carries signals representing the frame, not the word “Hi” directly.",
            "active": ["signal-path"],
            "calloutRegion": "signal-path",
            "readouts": [
              {
                "id": "original",
                "label": "Original message",
                "value": "Hi"
              },
              {
                "id": "representation",
                "label": "Current representation",
                "value": "Physical signals encoding the Ethernet frame"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Frame transmitted; Next compares the recovered message."
              }
            ]
          },
          {
            "id": "recovered",
            "label": "Receiver · Compare",
            "short": "Compare",
            "sentence": "Receiver: The receiving stack reverses encapsulation and delivers the recovered message to the application.",
            "why": "Different layers supplied different services around the same application data; the matching messages are the final evidence.",
            "active": ["receiver"],
            "calloutRegion": "receiver",
            "readouts": [
              {
                "id": "original",
                "label": "Original message",
                "value": "Hi"
              },
              {
                "id": "recovered",
                "label": "Recovered message",
                "value": "Hi"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Messages match. This comparison remains visible until you choose Previous or Reset."
              }
            ]
          }
        ]
      }
    ]
  }
}
